func shouldDeliver(event message, subscriber client) bool {
	if event.clientUniqueId == "" {
		return true
	}
	if event.clientUniqueId == subscriber.clientUniqueId {
		return false
	}
	return event.username == "" || event.username == subscriber.username
}
